<?php
namespace App\Tests\Runtime;
use App\Entity\{RuntimeTransaction,RuntimeTransactionLog};use App\Repository\BuilderEntityRepository;
use App\Runtime\{RuntimeApiEntityActionService,RuntimeExternalJsonClient,RuntimeTransactionService,RuntimeExecutionContext,RuntimeEntityDefinitionResolver,RuntimeEnvironmentIdentityResolver,PermissionResolver,RuntimeHttpException};use Doctrine\ORM\EntityManagerInterface;use PHPUnit\Framework\TestCase;
final class RuntimeExpenseSelectionTest extends TestCase {
 private function body(bool$options=false):array{return json_decode(file_get_contents('D:/opencode/conversao-sc/.runtime/ciw-completion-20261028/container-expense-default-selection/local/'.($options?'selection-root-options.json':'selection-process-success.json')),true,512,JSON_THROW_ON_ERROR);}
 private function invoke(bool$options,array$body,array&$sent,array&$logs,array$payload=[],bool$allowed=true,string$actor='test-actor',array$override=[],array$configOverride=[]):array{
  $em=$this->createStub(EntityManagerInterface::class);$em->method('persist')->willReturnCallback(static function($row)use(&$logs){if($row instanceof RuntimeTransactionLog)$logs[]=$row;});$perms=$this->createStub(PermissionResolver::class);$perms->method('hasPermission')->willReturn($allowed);
  $tx=new RuntimeTransactionService($em,$perms,new RuntimeExecutionContext(),$this->createStub(RuntimeEntityDefinitionResolver::class),$this->createStub(RuntimeEnvironmentIdentityResolver::class));(new \ReflectionProperty($tx,'current'))->setValue($tx,(new RuntimeTransaction())->setTenantId('default')->setRequestContext(['actor'=>['source'=>'authenticated-session','version'=>1,'username'=>$actor]]));
  $client=$this->createStub(RuntimeExternalJsonClient::class);$client->method('request')->willReturnCallback(static function($url,$method,$headers,$data)use(&$sent,$body){$sent[]=$data;return['status'=>200,'body'=>$body];});$service=new RuntimeApiEntityActionService($this->createStub(BuilderEntityRepository::class),$tx,$client,$perms);
  $operation=['code'=>$options?'despesas_selecao_opcoes':'selecionar_despesas','type'=>$options?'list':'custom','method'=>'POST','path'=>'http://127.0.0.1:19910/med/web/SursumPrograms/containers-processos','requestContextFields'=>['container_id'],'bodyTemplate'=>['resource'=>$options?'despesas-selecao':'impostos','operation'=>$options?'options':'selecionar_despesas'],'itemsPath'=>'data','itemPath'=>'data'];if(!$options)$operation['allowProcess']=true;$operation=array_replace($operation,$override);
  $fields=['container_id'=>['code'=>'container_id','dataType'=>'integer','label'=>'Container','required'=>true],'ordem_campo'=>['code'=>'ordem_campo','dataType'=>'string','label'=>'Campo','required'=>true],'ordem_direcao'=>['code'=>'ordem_direcao','dataType'=>'string','label'=>'Direcao','required'=>true],'despesa_ids'=>['code'=>'despesa_ids','dataType'=>'json','label'=>'Despesas','required'=>true,'collection'=>['itemType'=>'integer'],'optionsSource'=>['operationCode'=>'despesas_selecao_opcoes','valueField'=>'despesa_id','textField'=>'label','parameterFields'=>['ordem_campo','ordem_direcao']]]];
  $d=['entityCode'=>'container_despesas_selecao_progress','primaryKey'=>'container_id','apiBinding'=>['sourceCode'=>'motor_progress_container_processos'],'apiSource'=>['responseContract'=>'sursum-programs','authHeaders'=>[],'operations'=>[$operation]],'contextFields'=>[['field'=>'container_id','required'=>true,'readonly'=>true]],'fields'=>$fields];
  $p=['context'=>['container_id'=>123],'parameters'=>['ordem_campo'=>'ordem','ordem_direcao'=>'asc']+($options?[]:['despesa_ids'=>[40]])];$payload=array_replace($p,$payload);
  $config=['operation'=>$options?'options':'process','allowProcess'=>true,'permissionPrefix'=>'container_despesas_selecao_progress','contextFields'=>[['field'=>'container_id']],'processOptions'=>['operationCode'=>'selecionar_despesas','parameterFields'=>['ordem_campo','ordem_direcao','despesa_ids']],'fieldCode'=>'despesa_ids','processParameterOptions'=>true,'lookupParameterFields'=>['ordem_campo','ordem_direcao']];
  return(new \ReflectionMethod($service,$options?'options':'process'))->invoke($service,$d,array_replace($config,$configOverride),$payload);
 }
 public function testRealRootResponseImportsFullImagesAndActor():void{
  $sent=[];$logs=[];$r=$this->invoke(false,$this->body(),$sent,$logs);self::assertTrue($r['audit']['available']??false);self::assertSame([['resource'=>'impostos','operation'=>'selecionar_despesas','ordem_campo'=>'ordem','ordem_direcao'=>'asc','despesa_ids'=>[40],'container_id'=>123]],$sent);
  $events=array_values(array_filter($logs,fn($row)=>$row->getMetadata()['audit']['available']??false));self::assertCount(count($this->body()['audit']['changes'])+1,$events);self::assertSame($this->body()['audit']['before'],$events[0]->getBeforeData());self::assertSame('test-actor',$events[0]->getMetadata()['actor']['username']);
 }
 public function testRealOptionsForwardsOnlySignedEnumsAndValidatesPhysicalContext():void{
  $sent=[];$logs=[];$r=$this->invoke(true,$this->body(true),$sent,$logs);self::assertNotEmpty($r['data']);self::assertSame([['resource'=>'despesas-selecao','operation'=>'options','container_id'=>123,'ordem_campo'=>'ordem','ordem_direcao'=>'asc']],$sent);self::assertCount(1,$logs);self::assertSame([],$logs[0]->getBeforeData());
  foreach(['owner','duplicate','total','count','field']as$case){$b=$this->body(true);if($case==='owner')$b['data'][0]['container_id']=124;elseif($case==='duplicate'){$b['data'][]=$b['data'][0];++$b['total'];}elseif($case==='total')++$b['total'];elseif($case==='count'){$b['data']=array_fill(0,201,$b['data'][0]);$b['total']=201;}else$b['data'][0]['other']=1;$sent=[];$logs=[];try{$this->invoke(true,$b,$sent,$logs);self::fail($case);}catch(RuntimeHttpException$e){self::assertSame(502,$e->getStatusCode());}}
 }
 public function testBadSelectionOrderIdentityAndContextNeverReachTransport():void{
  foreach(['empty','duplicate','type','limit','enum','extra','context','actor','permission','binding']as$case){$p=['ordem_campo'=>'ordem','ordem_direcao'=>'asc','despesa_ids'=>[40]];switch($case){case'empty':$p['despesa_ids']=[];break;case'duplicate':$p['despesa_ids']=[40,40];break;case'type':$p['despesa_ids']=['40'];break;case'limit':$p['despesa_ids']=range(1,101);break;case'enum':$p['ordem_campo']='ordem;delete';break;case'extra':$p['percentual']=99;break;}$sent=[];$logs=[];try{$this->invoke(false,$this->body(),$sent,$logs,['parameters'=>$p]+($case==='context'?['context'=>[]]:[]),$case!=='permission',$case==='actor'?'':'test-actor',$case==='binding'?['bodyTemplate'=>['resource'=>'custos','operation'=>'fechar']]:[]);self::fail($case);}catch(RuntimeHttpException$e){self::assertContains($e->getStatusCode(),[401,403,422]);}self::assertSame([],$sent,$case);}
 }
 public function testCommittedBadAuditOrPresentationIsResolvedWithoutFictitiousSnapshots():void{
  foreach(['actor','partial','item','presentation','commit']as$case){$b=$this->body();if($case==='actor')$b['audit']['actor']['login']='other';elseif($case==='partial')unset($b['audit']['changes'][0]['after']['usuario_id']);elseif($case==='item')$b['audit']['changes'][0]['resource']='itens_container';elseif($case==='presentation')$b['data']=['type'=>'script','script'=>'bad'];else unset($b['committed']);$sent=[];$logs=[];try{$r=$this->invoke(false,$b,$sent,$logs);self::assertNotSame('commit',$case);self::assertStringContainsString('Nao repita',$r['result']['message']);if($case!=='presentation')foreach($logs as$log){self::assertSame([],$log->getBeforeData());self::assertSame([],$log->getAfterData());}}catch(RuntimeHttpException$e){self::assertSame('commit',$case);self::assertSame(502,$e->getStatusCode());}}
 }
 public function testOptionsNeedsBothSignedEnumsAndFixedReadonlyContextBeforeTransport():void{
  foreach(['missing','extra','type','uppercase','context','extraContext','actor','signed']as$case){
   $payload=['parameters'=>['ordem_campo'=>'ordem','ordem_direcao'=>'asc']];$config=[];
   if($case==='missing')unset($payload['parameters']['ordem_direcao']);elseif($case==='extra')$payload['parameters']['container_id']=124;elseif($case==='type')$payload['parameters']['ordem_campo']=['ordem'];elseif($case==='uppercase')$payload['parameters']['ordem_direcao']='ASC';elseif($case==='context')$payload['context']=[];elseif($case==='extraContext')$payload['context']=['container_id'=>123,'empresa_id'=>1];elseif($case==='actor')$payload['actor']='other';else$config['lookupParameterFields']=[];
   $sent=[];$logs=[];try{$this->invoke(true,$this->body(true),$sent,$logs,$payload,true,'test-actor',[],$config);self::fail($case);}catch(RuntimeHttpException$e){self::assertSame(422,$e->getStatusCode(),$case);}self::assertSame([],$sent,$case);self::assertSame([],$logs,$case);
  }
 }
}
